socket.on('guess', (text, acknowledge) => {
  const correct = text === WORD;
  acknowledge(correct);

  if (!correct) {
    io.to(ROOM).emit('chat', { from: label, text });
    return;
  }

  io.to(socket.id).emit('correct', { word: WORD });
  io.to(ROOM).emit('announce', { winner: label, word: WORD });
});

