export async function startRealApplication(): Promise<ScenarioApplication> {
  const httpServer = createServer();
  const io = new SocketIoServer<ClientToServerEvents, ServerToClientEvents>(httpServer);
  registerDrawingGameHandlers(io);
  await listen(httpServer);

  const address = httpServer.address();
  if (!address || typeof address === 'string') {
    await closeSocketIo(io);
    throw new Error('Socket.IO did not receive a TCP address');
  }

  return createScenarioApplication(io, `http://127.0.0.1:${address.port}`, () => closeSocketIo(io));
}

export function startSmocketApplication(): ScenarioApplication {
  nextOrigin += 1;
  const url = `http://drawing-game-${nextOrigin}.smocket.test`;
  const io = new SmocketServer<ClientToServerEvents, ServerToClientEvents>(url);
  registerDrawingGameHandlers(io);

  return createScenarioApplication(io, url, () => io.close());
}

export async function resolve(specifier, context, nextResolve) {
  const fromSmocketBuild = context.parentURL?.includes('/examples/drawing-game/dist/smocket/');
  if (specifier === 'socket.io-client' && fromSmocketBuild) {
    return nextResolve(
      new URL('../../packages/smocket-client/dist/index.mjs', import.meta.url).href,
      context,
    );
  }
  const fromSmocketClient = context.parentURL?.includes('/packages/smocket-client/dist/');
  if (specifier === 'smocket' && (fromSmocketBuild || fromSmocketClient)) {
    return nextResolve(new URL('../../dist/index.js', import.meta.url).href, context);
  }
  return nextResolve(specifier, context);
}
